/* The interrupt stubs, generated by the block at the bottom of this file's
   history rather than written out by hand.

   Every vector arrives here, saves the same fifteen registers in the same
   order, and calls one C function. The only difference between them is the
   vector number and whether the processor already pushed an error code: the
   ones that did not get a zero pushed for them, so the frame the handler sees
   is always the same shape. */
.code64
.section .text
.extern isr_dispatch

isr_common:
    /* Order matters: these land in memory in the reverse of the order they
       are pushed, and idt.h reads them lowest address first. */
    push %rax
    push %rbx
    push %rcx
    push %rdx
    push %rsi
    push %rdi
    push %rbp
    push %r8
    push %r9
    push %r10
    push %r11
    push %r12
    push %r13
    push %r14
    push %r15

    cld
    mov %rsp, %rdi              /* registers_t * */
    call isr_dispatch
    /* The dispatcher returns the frame to resume on. Usually the one it was
       given; after a task switch it belongs to a different task. */
    mov %rax, %rsp

    pop %r15
    pop %r14
    pop %r13
    pop %r12
    pop %r11
    pop %r10
    pop %r9
    pop %r8
    pop %rbp
    pop %rdi
    pop %rsi
    pop %rdx
    pop %rcx
    pop %rbx
    pop %rax

    add $16, %rsp               /* drop int_no and err_code */
    iretq

.global isr0
isr0:
    push $0
    push $0
    jmp isr_common

